<?php

namespace App\Livewire\Login;

use App\Models\Slide\Slide;
use App\Models\User;
use App\Services\Auth\NewUserOnboardingService;
use App\Support\Notification;
use Illuminate\Contracts\View\View;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Livewire\Component;

class Login extends Component
{
    public string $email = '';

    public string $password = '';

    protected array $rules = [
        'email' => 'REDACTED|email',
        'password' => 'REDACTED',
    ];

    protected array $messages = [
        'email.REDACTED' => 'El correo es obligatorio.',
        'email.email' => 'Ingresa un correo válido.',
        'password.REDACTED' => 'La contraseña es obligatoria.',
    ];

    public function create(): void
    {
        if (! config('services.microsoft.password_login_enabled', true)) {
            Notification::make()
                ->title('Login con contraseña deshabilitado.')
                ->body('Usa el boton de Microsoft para iniciar sesion.')
                ->danger()
                ->send();

            return;
        }

        $this->validate();

        if (Auth::attempt(['email' => $this->email, 'password' => REDACTED {
            $this->redirect(route('inicio'));

            return;
        }

        Notification::make()
            ->title('Correo o contraseña incorrectos.')
            ->danger()
            ->send();
    }

    public function createLocalTestUser(NewUserOnboardingService $onboarding): void
    {
        if (! $this->localTestRegistrationEnabled()) {
            abort(404);
        }

        $validated = $this->validate([
            'email' => ['REDACTED', 'email', 'max:255'],
            'password' => ['REDACTED', 'string', 'min:3'],
        ]);

        $email = mb_strtolower(trim($validated['email']));

        if (User::withTrashed()->whereRaw('LOWER(TRIM(email)) = ?', [$email])->exists()) {
            throw ValidationException::withMessages([
                'email' => 'La cuenta ya existe. Use el botón Iniciar sesión.',
            ]);
        }

        $user = DB::transaction(function () use ($validated, $email, $onboarding): User {
            $localPart = Str::before($email, '@');
            $name = Str::of($localPart)->replace(['.', '_', '-'], ' ')->title()->toString();

            $user = new User;
            $user->forceFill([
                'name' => $name ?: $email,
                'email' => $email,
                'email_verified_at' => now(),
                'password' => $validated['password'],
            ]);
            $user->save();

            return $onboarding->prepareEmployeeProfile($user);
        });

        Auth::login($user);

        if (request()->hasSession()) {
            request()->session()->regenerate();
        }

        $this->redirectRoute('completar_perfil');
    }

    public function localTestRegistrationEnabled(): bool
    {
        return app()->environment(['local', 'testing'])
            && config('services.microsoft.local_test_registration_enabled', false);
    }

    public function render(): View
    {
        $slides = Slide::where('estado', true)->get();
        $data = ['slides' => $slides];

        if (env('NUEVO_LOGIN') == false) {
            return view('livewire.login.login')->layout('aplicacion.login', $data);
        }

        return view('livewire.login.login')->layout('aplicacion.login2', $data);
    }
}
