const patch = "*** Begin Patch
*** Add File: /tmp/dump_inventory.php
+<?php
+
+$path = $argv[1] ?? '';
+$handle = fopen($path, 'rb');
+
+if (! $handle) {
+    fwrite(STDERR, "Cannot open dump.\n");
+    exit(1);
+}
+
+$tables = [];
+$currentTable = null;
+$inCreate = false;
+
+while (($line = fgets($handle)) !== false) {
+    if (preg_match('/^CREATE TABLE `([^`]+)`/', $line, $match)) {
+        $currentTable = $match[1];
+        $tables[$currentTable] ??= ['columns' => [], 'rows' => 0, 'inserts' => 0];
+        $inCreate = true;
+        continue;
+    }
+
+    if ($inCreate) {
+        if (preg_match('/^  `([^`]+)`/', $line, $match)) {
+            $tables[$currentTable]['columns'][] = $match[1];
+        }
+
+        if (str_starts_with($line, ') ENGINE=')) {
+            $inCreate = false;
+            $currentTable = null;
+        }
+
+        continue;
+    }
+
+    if (preg_match('/^INSERT INTO `([^`]+)` VALUES (.*);\s*$/s', $line, $match)) {
+        $table = $match[1];
+        $tables[$table] ??= ['columns' => [], 'rows' => 0, 'inserts' => 0];
+        $tables[$table]['inserts']++;
+        $tables[$table]['rows'] += countRows($match[2]);
+    }
+}
+
+fclose($handle);
+ksort($tables);
+
+foreach ($tables as $table => $metadata) {
+    printf("%s\t%d\t%d\t%s\n", $table, $metadata['rows'], count($metadata['columns']), implode(',', $metadata['columns']));
+}
+
+function countRows(string $values): int
+{
+    $count = 0;
+    $quoted = false;
+    $escaped = false;
+    $depth = 0;
+    $length = strlen($values);
+
+    for ($index = 0; $index < $length; $index++) {
+        $character = $values[$index];
+
+        if ($quoted) {
+            if ($escaped) {
+                $escaped = false;
+            } elseif ($character === '\\') {
+                $escaped = true;
+            } elseif ($character === "'") {
+                $quoted = false;
+            }
+
+            continue;
+        }
+
+        if ($character === "'") {
+            $quoted = true;
+        } elseif ($character === '(') {
+            if ($depth === 0) {
+                $count++;
+            }
+            $depth++;
+        } elseif ($character === ')') {
+            $depth--;
+        }
+    }
+
+    return $count;
+}
*** End Patch";
text(await tools.apply_patch(patch));

payload.message:
La ruta de migración más compatible es restaurar este dump en una base MySQL completamente vacía y luego ejecutar las migraciones pendientes del proyecto. Eso permite que las migraciones actuales transformen correctamente datos heredados —por ejemplo, contrapartes y catálogos— en vez de insertar filas antiguas después de que esas columnas ya fueron eliminadas.

Prepararé un seeder protegido que:

- solo funciona con autorización explícita;
- se niega a tocar una base que ya tenga tablas;
- conserva IDs y relaciones del dump;
- valida opcionalmente su SHA-256;
- importa estructura y datos, pero omite los `DROP TABLE`;
- deja la base lista para ejecutar las migraciones actuales.

No agregaré el dump al repositorio porque contiene datos de producción.

